class PythonSyntaxHighlighter(QSyntaxHighlighter):
    """Small Python syntax highlighter for node-code inspection dialogs."""

    _DARK_TOKEN_COLORS = {
        "keyword": "#60a5fa",
        "builtin": "#c084fc",
        "callable": "#fbbf24",
        "number": "#fca5a5",
        "string": "#86efac",
        "comment": "#94a3b8",
    }
    _LIGHT_TOKEN_COLORS = {
        "keyword": "#1d4ed8",
        "builtin": "#7e22ce",
        "callable": "#92400e",
        "number": "#b91c1c",
        "string": "#166534",
        "comment": "#475569",
    }

    _KEYWORDS = (
        "False",
        "None",
        "True",
        "and",
        "as",
        "assert",
        "break",
        "class",
        "continue",
        "def",
        "del",
        "elif",
        "else",
        "except",
        "finally",
        "for",
        "from",
        "global",
        "if",
        "import",
        "in",
        "is",
        "lambda",
        "nonlocal",
        "not",
        "or",
        "pass",
        "raise",
        "return",
        "try",
        "while",
        "with",
        "yield",
    )
    _BUILTINS = (
        "bool",
        "dict",
        "float",
        "int",
        "len",
        "list",
        "max",
        "min",
        "np",
        "range",
        "repr",
        "set",
        "str",
        "tuple",
    )

    def __init__(self, document, *, palette: QPalette | None = None):
        super().__init__(document)
        self._rules: list[tuple[re.Pattern[str], QTextCharFormat]] = []
        self._string_format = QTextCharFormat()
        self._comment_format = QTextCharFormat()
        if palette is None:
            application = QApplication.instance()
            palette = application.palette() if application is not None else QPalette()
        self.set_palette(palette)

    def set_palette(self, palette: QPalette) -> None:
        """Rebuild token formats for ``palette`` and refresh existing text."""

        token_colors = (
            self._DARK_TOKEN_COLORS
            if palette_is_dark(palette)
            else self._LIGHT_TOKEN_COLORS
        )
        self._rules.clear()
        self._add_rule(
            rf"\b({'|'.join(self._KEYWORDS)})\b",
            token_colors["keyword"],
            bold=True,
        )
        self._add_rule(
            rf"\b({'|'.join(self._BUILTINS)})\b",
            token_colors["builtin"],
        )
        self._add_rule(r"\b[A-Za-z_]\w*(?=\()", token_colors["callable"])
        self._add_rule(r"\b\d+(\.\d+)?\b", token_colors["number"])
        self._string_format = self._format(token_colors["string"])
        self._comment_format = self._format(
            token_colors["comment"],
            italic=True,
        )
        self.rehighlight()

    def highlightBlock(self, text: str) -> None:  # noqa: N802
        for pattern, text_format in self._rules:
            for match in pattern.finditer(text):
                self.setFormat(
                    match.start(),
                    match.end() - match.start(),
                    text_format,
                )
        for match in re.finditer(r"(['\"])(?:\\.|(?!\1).)*\1", text):
            self.setFormat(
                match.start(),
                match.end() - match.start(),
                self._string_format,
            )
        comment_start = text.find("#")
        if comment_start >= 0:
            self.setFormat(
                comment_start,
                len(text) - comment_start,
                self._comment_format,
            )

    def _add_rule(
        self,
        pattern: str,
        color: str,
        *,
        bold: bool = False,
        italic: bool = False,
    ) -> None:
        self._rules.append((re.compile(pattern), self._format(color, bold, italic)))

    @staticmethod
    def _format(
        color: str,
        bold: bool = False,
        italic: bool = False,
    ) -> QTextCharFormat:
        text_format = QTextCharFormat()
        text_format.setForeground(QColor(color))
        if bold:
            text_format.setFontWeight(QFont.Bold)
        if italic:
            text_format.setFontItalic(True)
        return text_format


class _PaletteAwarePythonCodeEditor(QPlainTextEdit):
    """Read-only code editor that keeps syntax colors in sync with Qt."""

    def changeEvent(self, event) -> None:  # noqa: N802
        super().changeEvent(event)
        if event.type() not in {QEvent.PaletteChange, QEvent.StyleChange}:
            return
        highlighter = getattr(self, "_vipp_python_highlighter", None)
        if highlighter is not None:
            highlighter.set_palette(self.palette())


def _prepare_colocalization_scatter_density(
    channel_1: np.ndarray,
    channel_2: np.ndarray,
    *,
    threshold_1: float,
    threshold_2: float,
    roi_mask: np.ndarray | None,
    intensity_max: float,
    bins: int,
    range_percentile: float = 100.0,
    progress=None,
    include_full_ranges: bool = False,
) -> tuple:
    """Compatibility facade for the extracted scatter-density calculation."""
    return _prepare_scatter_density(
        channel_1,
        channel_2,
        threshold_1=threshold_1,
        threshold_2=threshold_2,
        roi_mask=roi_mask,
        intensity_max=intensity_max,
        bins=bins,
        range_percentile=range_percentile,
        progress=progress,
        chunk_elements=INSPECTOR_STATISTICS_CHUNK_ELEMENTS,
        include_full_ranges=include_full_ranges,
    )


def _count_colocalization_scatter_thresholds(
    channel_1: np.ndarray,
    channel_2: np.ndarray,
    *,
    threshold_1: float,
    threshold_2: float,
    roi_mask: np.ndarray | None,
    progress=None,
) -> tuple[int, int]:
    """Compatibility facade for exact counts without density recomputation."""
    return _count_scatter_thresholds(
        channel_1,
        channel_2,
        threshold_1=threshold_1,
        threshold_2=threshold_2,
        roi_mask=roi_mask,
        progress=progress,
        chunk_elements=INSPECTOR_STATISTICS_CHUNK_ELEMENTS,
    )


